// Generated from src/registry/sources/control-ui/recipes/app-shell-header.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const appShellHeaderKnobs = [
  "--cui-app-shell-header-height",
  "--cui-app-shell-header-padding-inline",
  "--cui-app-shell-header-background",
  "--cui-app-shell-header-border-color",
  "--cui-app-shell-header-border-width",
] as const;
export type AppShellHeaderKnobStyle = Partial<Record<(typeof appShellHeaderKnobs)[number], string>>;

@layer components {
  :where([data-control-family="app-shell-header"][data-slot="root"]) {
    --cui-app-shell-header-height: calc(var(--spacing) * 14);
    --cui-app-shell-header-padding-inline: calc(var(--spacing) * 4);
    --cui-app-shell-header-background: var(--background);
    --cui-app-shell-header-border-width: 1px;
    --cui-app-shell-header-border-color: var(--border);
    min-height: var(--cui-app-shell-header-height);
    padding-inline: var(--cui-app-shell-header-padding-inline);
    background: var(--cui-app-shell-header-background);
    border-block-end: var(--cui-app-shell-header-border-width) solid var(--cui-app-shell-header-border-color);
  }
}

@property --cui-app-shell-header-height {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-app-shell-header-padding-inline {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-app-shell-header-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-app-shell-header-border-color {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --cui-app-shell-header-border-width {
  syntax: "<length>";
  inherits: true;
  initial-value: 0px;
}

"use client";

import type { ComponentProps, CSSProperties } from "react";
import type { AppShellHeaderKnobStyle } from "@/components/control-ui/knob-contracts/app-shell-header-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { type PageScroll, PageScrollContext, usePageScroll } from "@/components/control-ui/ui/page-layout";
import { SidebarInset, type SidebarInsetProps, SidebarProvider, type SidebarProviderProps } from "@/components/control-ui/ui/sidebar";

export type AppShellProps = SidebarProviderProps & { scroll?: PageScroll };

export function AppShell({ scroll = "auto", layout = "viewport", className, ...props }: AppShellProps) {
  const resolvedScroll = usePageScroll(scroll);
  return (
    <PageScrollContext.Provider value={resolvedScroll}>
      <SidebarProvider
        data-app-shell=""
        data-scroll={resolvedScroll}
        layout={layout}
        className={cn(layout === "viewport" && (resolvedScroll === "page" ? "min-h-dvh" : "h-dvh min-h-0 overflow-hidden"), className)}
        {...props}
      />
    </PageScrollContext.Provider>
  );
}

export function AppShellContent({ className, ...props }: SidebarInsetProps) {
  const scroll = usePageScroll();
  return <SidebarInset data-app-shell-content="" className={cn("min-h-0", scroll !== "page" && "overflow-hidden", className)} {...props} />;
}

export type AppShellHeaderProps = Omit<ComponentProps<"header">, "style"> & {
  style?: CSSProperties & AppShellHeaderKnobStyle;
};

export function AppShellHeader({ className, ...props }: AppShellHeaderProps) {
  return (
    <header
      data-control-ui="app-shell"
      data-control-family="app-shell-header"
      data-slot="root"
      className={cn("sticky top-0 z-30 flex shrink-0 items-center gap-2", className)}
      {...props}
    />
  );
}
